191	/**
192	 * Maps a recorded execution to the gate result that goes on the receipt. The one place the precedence
193	 * between repository invalidation, setup failure, and the gate's own outcome is decided, so the local and CI
194	 * paths cannot classify the same execution differently.
195	 *
196	 * `invalidated` is supplied by the caller because each path compares its own notion of an unchanged
197	 * repository: the local path also requires the bound branch, the CI path also requires the caller SHA.
198	 *
199	 * Every non-passing setup outcome collapses to one `setup_failed`. The distinction between a step that timed
200	 * out and one that exited non-zero lives in the recorded step itself, so the receipt keeps it without adding
201	 * a contract value that consumers would have to pin against.
202	 */
203	export function classifyGateOutcome(input: {
204	  setup: readonly SetupStepExecution[];
205	  gate: GateProcessResult | null;
206	  invalidated: boolean;
207	}): GateReceiptResult {
208	  // Evidence integrity outranks classification: a receipt must never claim to describe a HEAD it does not.
209	  if (input.invalidated) {
210	    return 'invalidated';
211	  }
212	  if (input.setup.some((step) => step.process.result !== 'passed')) {
213	    return 'setup_failed';
214	  }
215	  // Setup passed, so the sequence should have reached the gate. A missing gate result means execution broke
216	  // rather than that the gate passed.
217	  return input.gate?.result ?? 'execution_error';
218	}
