  const gitPath = await git(repoRoot, ['rev-parse', '--git-path', relativePath]);
  return path.isAbsolute(gitPath) ? gitPath : path.resolve(repoRoot, gitPath);
}

export async function refExists(repoRoot: string, ref: string) {
