export function getProtocolCommandRules() {
  return PROTOCOL_COMMAND_RULES;
}

export function createThreadloopProgram(handlers: ThreadloopCliHandlers) {
  const program = new Command();

  program
    .name('threadloop')
    .description('Task-first, repo-local session memory that generates review-ready artifacts')
    .version('0.1.0')
    .showHelpAfterError(false)
    .configureOutput({
      writeOut: (text) => process.stdout.write(text),
      writeErr: () => {},
    })
    .exitOverride();

  program.command('init').description('Initialize ThreadLoop in the current Git repo').action(handlers.init);


program.parseAsync(process.argv).catch(handleError);

function run<T extends unknown[]>(handler: (...args: T) => Promise<void>) {
  return (...args: T) => handler(...args).catch(handleError);
}

function commandAction<T extends unknown[]>(
  commandName: string,
  handler: (context: ReturnType<typeof createCommandContext>, ...args: T) => void | Promise<void>,
) {
  return (...args: [...T, Command]) => {
    const command = args.at(-1);
    if (!(command instanceof Command)) {
      throw createInvalidArgumentError('ThreadLoop could not determine the invoked command context.');
    }

    return Promise.resolve(handler(createCommandContext(commandName, command), ...(args.slice(0, -1) as T))).catch(
      handleError,
    );
  };
}

function handleError(error: unknown) {
  if (
    error instanceof CommanderError &&
    (error.code === 'commander.version' || error.code === 'commander.help' || error.code.startsWith('commander.help'))
  ) {
    process.exitCode = 0;
    return;
  }

  const json = process.argv.includes('--json');
  const command = detectInvokedCommand(process.argv.slice(2));
  const threadloopError =
    error instanceof CommanderError
      ? createInvalidArgumentError(error.message, { commander_code: error.code })
      : toThreadloopError(error);

  process.stderr.write(
    `${renderCommandFailure(
      command,
      {
        code: threadloopError.code,
        message: threadloopError.message,
        ...(threadloopError.details ? { details: threadloopError.details } : {}),
      },
      json,
    )}\n`,
  );
  process.exitCode = error instanceof CommanderError ? error.exitCode : 1;
}

function detectInvokedCommand(argv: string[]) {
  const tokens = argv.filter((token) => token !== '--json');
  if (tokens[0] === 'session' && tokens[1] === 'gate' && ['run', 'import'].includes(tokens[2] ?? '')) {
    return `session gate ${tokens[2]}`;
  }
  if (tokens[0] === 'session' && tokens[1] === 'review' && tokens[2] === 'import') {
    return 'session review import';
  }
  if (tokens[0] === 'audit' && ['show', 'verify', 'export'].includes(tokens[1] ?? '')) {
    return `audit ${tokens[1]}`;
  }
  if (tokens[0] === 'session' && tokens[1]) {
    return `session ${tokens[1]}`;
  }

  if (tokens[0] === 'artifact' && tokens[1] === 'generate') {
    return 'artifact generate';
  }

  return tokens[0] ?? 'threadloop';
}
    throw new InvalidArgumentError('Input must be valid JSON.');
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new InvalidArgumentError('Input must be a non-null JSON object.');
  }
  return parsed as Record<string, unknown>;
}

function parseIntervalSeconds(value: string): number {
  const parsed = parseInt(value, 10);
  if (!Number.isFinite(parsed) || parsed < 1) {
    throw new InvalidArgumentError('Interval must be a positive number of seconds (minimum 1)');
  }
  return parsed;
}

function withJsonOption<T extends Command>(command: T) {
  return command.addOption(new Option('--json', 'Output machine-readable JSON'));
}

