    { cwd: projectRoot, maxBuffer: 10 * 1024 * 1024 },
  );

  process.env[THREADLOOP_TEST_CLI_ENV] = path.join(bundleDirectory, 'cli.js');

  return async () => {
    delete process.env[THREADLOOP_TEST_CLI_ENV];
    await rm(bundleDirectory, { recursive: true, force: true });
  };
}

