    writeCommandSuccess(context, {
      text: ['No active session.'],
      data: { session: null, task: null, entries: { count: 0, kinds: {} }, repo_snapshot: null },
    });
    return;
  }

  const { task, session } = result.active;
  const counts = countEntryKinds(result.entries);

  writeCommandSuccess(context, {
