    const started = JSON.parse(
      (
        await execFileAsync(
          'npx',
          ['threadloop', 'session', 'start', 'Packaged namespace', '--goal', 'Verify namespaced session CLI', '--json'],
          { cwd: consumerRepo },
        )
      ).stdout,
    ) as { data: { session_id: string } };

    const captured = JSON.parse(
      (
        await execFileAsync(
          'npx',
          [
            'threadloop',
            'session',
            'capture',
            'note',
            'Explicit packaged flow works',
            '--session',
            started.data.session_id,
            '--json',
          ],
          { cwd: consumerRepo },
        )
      ).stdout,
    ) as { data: { session_id: string; entry: { body: string } } };
    expect(captured.data.session_id).toBe(started.data.session_id);
    expect(captured.data.entry.body).toBe('Explicit packaged flow works');

    const next = JSON.parse(
      (
        await execFileAsync('npx', ['threadloop', 'session', 'next', '--session', started.data.session_id, '--json'], {
          cwd: consumerRepo,
        })
      ).stdout,
    ) as { data: { candidate: { target_state: string; executable: boolean } } };
    expect(next.data.candidate).toMatchObject({ target_state: 'framed', executable: true });

    const transitioned = JSON.parse(
      (
        await execFileAsync(
          'npx',
          [
            'threadloop',
            'session',
            'transition',
            'framed',
            '--session',
            started.data.session_id,
            '--expected-state-version',
            '0',
            '--idempotency-key',
            'packaged:framed',
            '--actor',
            'agent',
            '--input',
            '{}',
            '--json',
          ],
          { cwd: consumerRepo },
        )
      ).stdout,
    ) as { data: { lifecycle: { state: string; state_version: number } } };
    expect(transitioned.data.lifecycle).toEqual({ state: 'framed', state_version: 1, blocked_from_state: null });

    const sessionStatus = JSON.parse(
      (
        await execFileAsync(
          'npx',
          ['threadloop', 'session', 'status', '--session', started.data.session_id, '--json'],
          { cwd: consumerRepo },
        )
      ).stdout,
    ) as { data: { session_id: string; entries: { count: number; kinds: Record<string, number> } } };
    expect(sessionStatus.data.session_id).toBe(started.data.session_id);
    expect(sessionStatus.data.entries.count).toBe(2);
    expect(sessionStatus.data.entries.kinds.note).toBe(1);
  }, 60_000);
});
