import { z } from 'zod';
import {
  ARTIFACT_KINDS,
  ENTRY_KINDS,
  ENTRY_SOURCES,
  HEARTBEAT_SOURCES,
  TASK_STATUS,
  TASK_STATUS_VALUES,
} from '../domain/types.js';

const persistedTaskStatusSchema = z
  .union([z.enum(TASK_STATUS_VALUES), z.literal('active')])
  .transform((status) => (status === 'active' ? TASK_STATUS.QUEUED : status));

export const taskSchema = z.object({
  id: z.string(),
  title: z.string(),
  goal: z.string(),
  constraints: z.array(z.string()),
  issueRef: z.string().nullable().optional().default(null),
  repoRoot: z.string(),
  status: persistedTaskStatusSchema,
  stateVersion: z.number().int().nonnegative().optional().default(0),
  blockedFromState: z.enum(TASK_STATUS_VALUES).nullable().optional().default(null),
  createdAt: z.string(),
});

export const sessionSchema = z.object({
  id: z.string(),
  taskId: z.string(),
  startedAt: z.string(),
  endedAt: z.string().nullable(),
  baseRef: z.string().nullable(),
  branch: z.string(),
  headSha: z.string(),
  lastHeartbeatAt: z.string().nullable().optional().default(null),
  lastHeartbeatSource: z.enum(HEARTBEAT_SOURCES).nullable().optional().default(null),
});

export const entrySchema = z.object({
  id: z.string(),
  sessionId: z.string(),
  kind: z.enum(ENTRY_KINDS),
  body: z.string(),
  metadata: z.record(z.string(), z.unknown()),
  createdAt: z.string(),
  source: z.enum(ENTRY_SOURCES),
});

export const artifactSchema = z.object({
  id: z.string(),
  sessionId: z.string(),
  kind: z.enum(ARTIFACT_KINDS),
  path: z.string(),
  templateVersion: z.string(),
  generatedAt: z.string(),
});

export const activeStateSchema = z.object({
  taskId: z.string(),
  sessionId: z.string(),
});

export const stateDataSchema = z
  .object({
    tasks: z.array(taskSchema),
    sessions: z.array(sessionSchema),
    entries: z.array(entrySchema),
    artifacts: z.array(artifactSchema),
    active: activeStateSchema.nullable(),
    activeSessions: z.array(activeStateSchema).optional(),
  })
  .transform((state) => ({
    ...state,
    tasks: state.tasks.map((task) => ({
      ...task,
      issueRef: task.issueRef ?? null,
      stateVersion: task.stateVersion ?? 0,
      blockedFromState: task.blockedFromState ?? null,
    })),
    activeSessions: state.activeSessions ?? (state.active ? [state.active] : []),
  }));

export const threadloopConfigSchema = z.object({
  version: z.literal(1),
  createdAt: z.string(),
});
import { describe, expect, it } from 'vitest';
import {
  CURRENT_SCHEMA_VERSION,
  EXPLICIT_INIT_MIGRATION_MIN_SCHEMA_VERSION,
  requiresExplicitInitMigration,
} from '../../src/adapters/fs/sqlite-store.js';
import { taskSchema } from '../../src/schemas/state.js';

const task = {
  id: 'task_1',
  title: 'Schema boundary',
  goal: 'Validate persisted lifecycle states',
  constraints: [],
  issueRef: null,
  repoRoot: '/repo',
  status: 'verifying',
  stateVersion: 4,
  blockedFromState: 'reviewing',
  createdAt: '2026-07-24T00:00:00.000Z',
};

describe('task state schema', () => {
  it('constructs and accepts current lifecycle values for status fields', () => {
    expect(taskSchema.parse(task)).toMatchObject({
      status: 'verifying',
      blockedFromState: 'reviewing',
    });
  });

  it('normalizes the legacy active state and rejects unknown lifecycle values', () => {
    expect(taskSchema.parse({ ...task, status: 'active' })).toMatchObject({
      status: 'queued',
    });
    expect(taskSchema.safeParse({ ...task, status: 'unknown' }).success).toBe(false);
    expect(taskSchema.safeParse({ ...task, blockedFromState: 'unknown' }).success).toBe(false);
  });
});

describe('storage schema migration policy', () => {
  it('requires explicit init for every semantic schema between the migration floor and current version', () => {
    expect(requiresExplicitInitMigration(EXPLICIT_INIT_MIGRATION_MIN_SCHEMA_VERSION - 1)).toBe(false);
    expect(requiresExplicitInitMigration(EXPLICIT_INIT_MIGRATION_MIN_SCHEMA_VERSION)).toBe(true);
    expect(requiresExplicitInitMigration(CURRENT_SCHEMA_VERSION)).toBe(false);
    expect(requiresExplicitInitMigration(CURRENT_SCHEMA_VERSION + 1)).toBe(false);

    expect(requiresExplicitInitMigration(7, 8)).toBe(true);
  });
});

