import re

p = 'tests/integration/session-transition.test.ts'
s = open(p).read()


def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:80])
    s = s.replace(old, new)


def delete_test(title_prefix):
    global s
    a = s.index(f"  it('{title_prefix}")
    m = re.search(r"\n  it(\.each)?\(", s[a + 5:])
    b = a + 5 + m.start() + 1
    s = s[:a] + s[b:]


def replace_between(start_needle, end_needle, replacement, keep_start=False):
    """Replace from start_needle (inclusive unless keep_start) up to end_needle (exclusive)."""
    global s
    a = s.index(start_needle)
    b = s.index(end_needle, a + len(start_needle))
    head = start_needle if keep_start else ''
    s = s[:a] + head + replacement + s[b:]


