"""Rewrite deniedGuards({code,message,owner_issue?},{code,description,owner_issue?}) calls as deny(...)."""
import sys

path = sys.argv[1]
src = open(path).read()


def match_close(text, start, open_ch, close_ch):
    """Index of the bracket closing the one at `start`, skipping strings and template literals."""
    depth = 0
    i = start
    quote = None
    while i < len(text):
        ch = text[i]
        if quote:
            if ch == '\\':
                i += 2
                continue
            if ch == quote:
                quote = None
            elif quote == '`' and text.startswith('${', i):
                end = match_close(text, i + 1, '{', '}')
                i = end + 1
                continue
        elif ch in '\'"`':
            quote = ch
        elif ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth -= 1
            if depth == 0:
                assert ch == close_ch, (ch, close_ch, text[start:i])
                return i
        i += 1
    raise ValueError('unbalanced')


def split_top_level(text, sep=','):
    parts, depth, quote, current, i = [], 0, None, '', 0
    while i < len(text):
        ch = text[i]
        if quote:
            current += ch
            if ch == '\\':
                current += text[i + 1]
                i += 2
                continue
            if ch == quote:
                quote = None
            elif quote == '`' and text.startswith('${', i):
                end = match_close(text, i + 1, '{', '}')
                current += text[i + 1:end + 1]
                i = end + 1
                continue
        elif ch in '\'"`':
            quote = ch
            current += ch
        elif ch in '([{':
            depth += 1
            current += ch
        elif ch in ')]}':
            depth -= 1
            current += ch
        elif ch == sep and depth == 0:
            parts.append(current)
            current = ''
        else:
            current += ch
        i += 1
    if current.strip():
        parts.append(current)
    return [part.strip() for part in parts if part.strip()]


def parse_object(text):
    text = text.strip()
    assert text.startswith('{') and text.endswith('}'), text
    fields = {}
    for pair in split_top_level(text[1:-1]):
        key, value = pair.split(':', 1)
        fields[key.strip()] = value.strip()
    return fields


out, cursor, converted = [], 0, 0
while True:
    start = src.find('deniedGuards(', cursor)
    if start == -1:
        break
    if src[start - len('function '):start] == 'function ':
        out.append(src[cursor:start + len('deniedGuards(')])
        cursor = start + len('deniedGuards(')
        continue
    paren = start + len('deniedGuards')
    close = match_close(src, paren, '(', ')')
    args = split_top_level(src[paren + 1:close])
    assert len(args) == 2, args
    failure, work = parse_object(args[0]), parse_object(args[1])
    assert set(failure) <= {'code', 'message', 'owner_issue'}, failure
    assert set(work) <= {'code', 'description', 'owner_issue'}, work
    assert failure.get('owner_issue') == work.get('owner_issue'), (failure, work)
    call = [failure['code'], failure['message'], work['code'], work['description']]
    if 'owner_issue' in failure:
        call.append(failure['owner_issue'])
    out.append(src[cursor:start] + 'deny(' + ', '.join(call) + ')')
    cursor = close + 1
    converted += 1
out.append(src[cursor:])
open(path, 'w').write(''.join(out))
print('converted', converted)

